export default class {
  async load() {
    // No framework API on the hot path: the worker applies the declared
    // policy to this request because of its URL, not because of the call.
    const response = await fetch('/api/products')
    this.products = await response.json()
  }

  async save(product) {
    // A successful write drops the cached reads it can affect — this path
    // and the collection it belongs to — so the next read is not stale.
    await fetch('/api/products', { method: 'POST', body: JSON.stringify(product) })
  }
}

