export class ProductsController {
  static GET() {
    // An ordinary value becomes a JSON response.
    return { products: ['anvil'] }
  }

  static POST(request) {
    // `body` exists only when one was sent, and holds raw text.
    const sent = request?.body ? JSON.parse(request.body.data) : {}
    return {
      status: 201,
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ created: sent }),
    }
  }
}

