struct ProductsController;

impl ProductsController {
    fn GET(_request: &YonRequest) -> YonResponse {
        // Json is in scope without an import. Rust has none in its standard
        // library and this compiles with no Cargo, so Tachyon supplies one
        // rather than leaving a handler to escape a string by hand.
        YonResponse::json(Json::map([
