@Controller
export class TicksController {
  // @Stream is how the route says it answers more than once, before it is
  // called. The server has to choose the streaming path before the handler
  // runs, so it cannot wait to see what comes back.
  //
  // The body still yields. Tachyon checks the two against each other: a
  // @Stream that never yields is refused, and so is a yield without one.
  @Stream
  static async *GET(request) {
    for (let level = 3; level > 0; level -= 1) {
      yield { sku: 'ANVIL-1', level }
      await new Promise((resume) => setTimeout(resume, 1000))
    }
  }
}

import time


@Controller
class TicksController:
    @staticmethod
    @Stream
    def GET(request):
        for level in range(3, 0, -1):
            yield {"sku": "ANVIL-1", "level": level}
            time.sleep(1)

// Kotlin's generator is `sequence { yield(…) }`, and a Sequence is what the
// prelude looks for. Not a Flow: that needs kotlinx-coroutines, which a bare
// kotlinc has not resolved — the same reason org.json is not on its classpath.
@Controller
object TicksController {
    @JvmStatic
    @Stream
    fun GET(request: YonRequest): Sequence<Map<String, Any>> = sequence {
        for (level in 3 downTo 1) {
            yield(mapOf("sku" to "ANVIL-1", "level" to level))
        }
    }
}

// yield return gives an IEnumerable; the asynchronous spelling gives an
// IAsyncEnumerable, and a handler that awaits per event is the realistic case
// for a stream. Both are accepted.
[Controller]
class TicksController
{
    [Stream]
    static async IAsyncEnumerable<object> GET(YonRequest request)
    {
        foreach (var sku in new[] { "ANVIL-1", "ANVIL-2" })
        {
            await Task.Delay(1000);
            yield return new { sku, level = 3 };
        }
    }
}

