export default class {
  @onMount
  subscribe() {
    // The browser owns reconnection and resends its last event id.
    const stream = new EventSource('/ticks')
    stream.addEventListener('message', (event) => {
      this.levels = [...this.levels, JSON.parse(event.data)]
    })
  }
}

// EventSource cannot send headers, so a stream behind an Authorization
// header is read with fetch instead. Same route, same events — the
// parsing is the only thing you take on.
export default class {
  levels: string[] = []

  async watch(): Promise<void> {
    const response = await fetch('/ticks', {
      headers: { authorization: `Bearer ${this.token}`, accept: 'text/event-stream' },
    })
    const reader = response.body!.pipeThrough(new TextDecoderStream()).getReader()
    let buffered = ''
    for (;;) {
      const { value, done } = await reader.read()
      if (done) break
      buffered += value
      // Events are separated by a blank line; a chunk may hold part of one.
      const parts = buffered.split('\n\n')
      buffered = parts.pop() ?? ''
      for (const part of parts) {
        const data = part.split('\n').find((line) => line.startsWith('data:'))
        if (data) this.levels.push(JSON.parse(data.slice(5)))
      }
      await this.tac.render()
    }
  }
}

